def is_valid_json_number(s):
    def is_uint(t):
        return t.isdigit() and (t == '0' or t[0] != '0')
    body = s[1:] if s.startswith('-') else s
    if not body:
        return False
    if 'e' in body or 'E' in body:
        idx = body.index('e') if 'e' in body else body.index('E')
        mantissa, exponent = body[:idx], body[idx + 1:]
    else:
        mantissa, exponent = body, None
    int_part, frac_part = mantissa.split('.', 1) if '.' in mantissa else (mantissa, None)
    if not is_uint(int_part) or (frac_part is not None and not frac_part.isdigit()):
        return False
    if exponent is not None:
        exponent = exponent[1:] if exponent[:1] in ('+', '-') else exponent
        return exponent.isdigit() and len(exponent) > 0
    return True

