    eh = int(end_hhmm[:2])
    return f"{(sh + eh) // 2:02d}:00"

def count_weekends_in_day_range(start_day_num, end_day_num):
    total_days = end_day_num - start_day_num + 1
    count = (total_days // 7) * 2
    start_weekday = start_day_num % 7
    for offset in range(total_days % 7):
        if (start_weekday + offset) % 7 in (5, 6):
            count += 1
    return count

