def longest_increasing_run_start(lst):
    if not lst:
        return -1
    starts = [0] * len(lst)
    lengths = [1] * len(lst)
    for i in range(1, len(lst)):
        if lst[i] > lst[i - 1]:
            starts[i] = starts[i - 1]
            lengths[i] = lengths[i - 1] + 1
        else:
            starts[i] = i
            lengths[i] = 1
    best_i = max(range(len(lst)), key=lambda i: (lengths[i], -starts[i]))
    return starts[best_i]

