def alternating_sum_abs_diffs(lst):
    if len(lst) < 2:
        return 0
    total = 0
    sign = 1
    for i in range(len(lst) - 1):
        total += sign * abs(lst[i + 1] - lst[i])
        sign *= -1
    return total

import math

def fraction_from_continued(terms):
    def build(index):
        if index == len(terms) - 1:
            return terms[index], 1
        num, den = build(index + 1)
        a = terms[index]
        return a * num + den, num
    num, den = build(0)
    if den < 0:
        num, den = -num, -den
    g = math.gcd(num, den)
    return (num // g, den // g)

